arguments.command:
# Find where this SystemConfigurationUtility is
$searchPaths = @(
    "C:\Program Files",
    "C:\Program Files (x86)",
    "C:\RA",
    "C:\Users\$env:USERNAME\AppData",
    "C:\ProgramData\Rockwell"
)

Write-Host "Searching for SystemConfigurationUtility.ps1..." -ForegroundColor Yellow
Write-Host ""

foreach ($path in $searchPaths) {
    if (Test-Path $path) {
        $results = Get-ChildItem -Path $path -Recurse -Filter "*SystemConfiguration*" -ErrorAction SilentlyContinue | Where-Object {$_.Extension -in '.ps1', '.exe'}
        if ($results) {
            Write-Host "✓ Found in: $path" -ForegroundColor Green
            $results | Select-Object FullName, Name, LastWriteTime | Format-Table
        }
    }
}

# Also search by content
Write-Host ""
Write-Host "Searching for files containing 'ConfigureDCOMPermissions'..." -ForegroundColor Yellow
Get-ChildItem -Path "C:\Program Files*", "C:\RA", "C:\ProgramData\Rockwell" -Recurse -Filter "*.ps1" -ErrorAction SilentlyContinue | ForEach-Object {
    $content = Get-Content $_.FullName -ErrorAction SilentlyContinue
    if ($content -match "ConfigureDCOMPermissions") {
        Write-Host "✓ Found: $($_.FullName)" -ForegroundColor Green
    }
}

